-- WoSB living knowledge base: imported from user-provided sources on 2026-10-16.
CREATE TABLE IF NOT EXISTS wosb_sources(
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  kind TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 500,
  captured_at DATE,
  file_name TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS wosb_knowledge_records(
  record_id TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL,
  entity_key TEXT NOT NULL,
  name TEXT NOT NULL,
  normalized_name TEXT GENERATED ALWAYS AS (lower(regexp_replace(name,'[^a-zA-Z0-9]+',' ','g'))) STORED,
  record_type TEXT NOT NULL DEFAULT 'profile',
  data JSONB NOT NULL,
  source_id TEXT NOT NULL REFERENCES wosb_sources(id),
  source_ref TEXT,
  priority INTEGER NOT NULL DEFAULT 500,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  imported_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_wosb_records_entity ON wosb_knowledge_records(entity_type,entity_key,priority DESC) WHERE active=TRUE;
CREATE INDEX IF NOT EXISTS idx_wosb_records_name ON wosb_knowledge_records(normalized_name) WHERE active=TRUE;
CREATE INDEX IF NOT EXISTS idx_wosb_records_type ON wosb_knowledge_records(entity_type,record_type) WHERE active=TRUE;
CREATE INDEX IF NOT EXISTS idx_wosb_records_data_gin ON wosb_knowledge_records USING GIN(data);

CREATE TABLE IF NOT EXISTS wosb_corrections(
  id BIGSERIAL PRIMARY KEY,
  entity_type TEXT NOT NULL,
  entity_key TEXT NOT NULL,
  field_path TEXT NOT NULL,
  value_json JSONB NOT NULL,
  previous_value_json JSONB,
  correction_text TEXT,
  reason TEXT,
  created_by TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reverted_at TIMESTAMPTZ,
  reverted_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_wosb_corrections_active ON wosb_corrections(entity_type,entity_key,created_at DESC) WHERE active=TRUE;

CREATE TABLE IF NOT EXISTS wosb_question_feedback(
  id BIGSERIAL PRIMARY KEY,
  user_id TEXT NOT NULL,
  question TEXT NOT NULL,
  answer TEXT,
  helpful BOOLEAN,
  note TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO wosb_sources(id,title,kind,priority,captured_at,file_name,metadata)
SELECT x.id,x.title,x.kind,x.priority,CASE WHEN x.captured_at IS NULL THEN NULL ELSE x.captured_at::date END,x.file,COALESCE(x.metadata,'{}'::jsonb)
FROM jsonb_to_recordset($json$[{"id":"user_crew_skills_2026_10_16","title":"Crew skills screenshot","kind":"screenshot","priority":850,"captured_at":"2026-10-16","file":"image(20261016-030501).png"},{"id":"user_mines_2026_10_16","title":"Mine production screenshot","kind":"screenshot","priority":850,"captured_at":"2026-10-16","file":"image2222.png"},{"id":"user_trade_workbook_2026_10_16","title":"WOSB Trade workbook","kind":"spreadsheet","priority":850,"captured_at":"2026-10-16","file":"WOSB. Trade.xlsx"},{"id":"user_crafting_workbook_2026_10_16","title":"WOSB Crafting workbook","kind":"spreadsheet","priority":850,"captured_at":"2026-10-16","file":"WOSB Crafting.xlsx"},{"id":"wosbcraft_snapshot_2026_10_16","title":"WoSB Craft site snapshot","kind":"website_snapshot","priority":700,"captured_at":"2026-10-16","file":"www.wosbcraft.com.zip"},{"id":"wosbmap_ship_snapshot_2026_10_16","title":"WoSB Map ship list snapshot","kind":"website_snapshot","priority":600,"captured_at":"2026-10-16","file":"saveweb2zip-com-wosbmap-com (1).zip"},{"id":"wosbmap_map_snapshot_2026_10_16","title":"WoSB Map interactive map snapshot","kind":"website_snapshot","priority":650,"captured_at":"2026-10-16","file":"saveweb2zip-com-wosbmap-com.zip"}]$json$::jsonb) AS x(id text,title text,kind text,priority int,captured_at text,file text,metadata jsonb)
ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,kind=EXCLUDED.kind,priority=EXCLUDED.priority,captured_at=EXCLUDED.captured_at,file_name=EXCLUDED.file_name;

